signature-file.pseudocode:
F, M = 16, 3  # 시그니처 비트 수, 단어당 1인 비트 수
def word_sig(word):
    sig = 0
    for i in range(M):
        sig |= 1 << (hash((word, i)) % F)
    return sig

def block_sig(words):
    sig = 0
    for w in words:
        sig |= word_sig(w)  # 중첩 부호화(OR)
    return sig

def search(blocks, sigs, query_words):
    q = block_sig(query_words)
    result = []
    for blk, s in zip(blocks, sigs):
        if s & q == q:  # 비트 비교로 후보 선별
            if all(w in blk for w in query_words):
                result.append(blk)  # False Drop 제거
    return result

