simple-factory.pseudocode:
class ShapeFactory:
    @staticmethod
    def create(kind):
        # 조건 분기로 구체 객체 생성 (한 곳에 집중)
        if kind == 'circle':
            return Circle()
        if kind == 'square':
            return Square()
        # 제품 추가 시 이 메서드 수정 필요(OCP 위반)
        raise ValueError(kind)

shape = ShapeFactory.create('circle')  # 구체 클래스 모름
shape.draw()

simple-reflex-agent.pseudocode:
RULES = [  # 조건-행동 규칙 (위에서부터 우선 적용)
    (lambda s: s['dirty'], 'Suck'),
    (lambda s: s['loc'] == 'A', 'Right'),
    (lambda s: s['loc'] == 'B', 'Left'),
]

def simple_reflex_agent(percept):  # 이력·내부 상태 없음
    loc, dirty = percept  # 현재 지각만 사용
    state = {'loc': loc, 'dirty': dirty}
    for condition, action in RULES:
        if condition(state):
            return action

print(simple_reflex_agent(('A', True)))  # Suck
print(simple_reflex_agent(('A', False)))  # Right

simplified-payment-verification.pseudocode:
def verify_merkle(tx_hash, proof, root):
    # proof: [(형제 해시, 형제가 왼쪽인가)] 잎 → 루트 순
    h = tx_hash
    for sibling, is_left in proof:
        if is_left:
            h = sha256d(sibling + h)
        else:
            h = sha256d(h + sibling)
    return h == root  # 블록 헤더의 머클 루트와 비교

singleton-pattern.pseudocode:
class Singleton:
    _instance = None
    _lock = Lock()

    def __init__(self):
        # 외부 생성 금지(private 생성자 역할)
        raise RuntimeError('use get_instance()')

    @classmethod
    def get_instance(cls):
        if cls._instance is None:  # 1차 검사(락 없음)
            with cls._lock:  # Double-Checked Locking
                if cls._instance is None:  # 2차 검사
                    cls._instance = cls.__new__(cls)
        return cls._instance  # Java는 volatile 필요

singly-linked-list.pseudocode:
class Node:
    def __init__(self, data):
        self.data, self.next = data, None

def insert_after(prev, data):  # O(1)
    node = Node(data)
    node.next = prev.next
    prev.next = node

def delete(head, key):  # 선행 노드 탐색 필요 → O(n)
    if head and head.data == key:
        return head.next  # 머리 노드 삭제
    prev = head
    while prev and prev.next:
        if prev.next.data == key:
            prev.next = prev.next.next  # 건너뛰기 연결
            break
        prev = prev.next
    return head
